SELECT pancreactomy2_2.nppes_provider_last_org_name AS nppes_provider_last_org_name,   pancreactomy2_2.nppes_provider_state AS nppes_provider_state,   AVG(CAST(pancreactomy2_2.average_medicare_allowed_amt AS double precision)) AS avg_average_medicare_allowed_amt_ok,   AVG(CAST(pancreactomy2_2.average_medicare_payment_amt AS double precision)) AS avg_average_medicare_payment_amt_ok,   AVG(CAST(pancreactomy2_2.average_submitted_chrg_amt AS double precision)) AS avg_average_submitted_chrg_amt_ok,   COUNT(pancreactomy2_2.average_medicare_allowed_amt) AS cnt_average_medicare_allowed_amt_ok,   COUNT(pancreactomy2_2.average_medicare_payment_amt) AS cnt_average_medicare_payment_amt_ok,   COUNT(pancreactomy2_2.average_submitted_chrg_amt) AS cnt_average_submitted_chrg_amt_ok,   SUM(pancreactomy2_2.average_medicare_allowed_amt) AS sum_average_medicare_allowed_amt_ok,   SUM(pancreactomy2_2.average_medicare_payment_amt) AS sum_average_medicare_payment_amt_ok,   SUM(pancreactomy2_2.average_submitted_chrg_amt) AS sum_average_submitted_chrg_amt_ok,   SUM(pancreactomy2_2.line_srvc_cnt) AS sum_line_srvc_cnt_ok FROM pancreactomy2_2 WHERE ((pancreactomy2_2.hcpcs_description IN ('Pancreas procedure', 'Partial removal of pancreas', 'Partial removal of pancreas with attachment to small bowel', 'Partial removal of pancreas, bile duct and small bowel with connection of pancreas to small bowel')) AND (pancreactomy2_2.provider_type IN ('General Surgery', 'Surgical Oncology', 'Vascular Surgery'))) GROUP BY pancreactomy2_2.nppes_provider_last_org_name,   pancreactomy2_2.nppes_provider_state;
